fn next_entropy_u64() -> u64 {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0x6A09_E667_F3BC_C908);
    let counter = WORD_SEED.fetch_add(0x9E37_79B9_7F4A_7C15, Ordering::Relaxed);
    let mut x = nanos ^ counter.rotate_left(23) ^ 0xBB67_AE85_84CA_A73B;
    x ^= x >> 30;
    x = x.wrapping_mul(0xBF58_476D_1CE4_E5B9);
    x ^= x >> 27;
    x = x.wrapping_mul(0x94D0_49BB_1331_11EB);
    x ^ (x >> 31)
}

pub fn generate_words_local_part() -> String {
    let r1 = next_entropy_u64();
    let r2 = next_entropy_u64();
    let adj = ADJECTIVES[(r1 as usize) % ADJECTIVES.len()];
    let noun = NOUNS[(r2 as usize) % NOUNS.len()];
    let num = ((r1 ^ r2) % 90) + 10;
    format!("{}.{}{:02}", adj, noun, num)
}

pub fn generate_passphrase(word_count: usize, separator: &str) -> GeneratedPassphrase {
    let count = word_count.clamp(3, 12);
    let sep = if separator.is_empty() { "-" } else { separator };
    let mut words = Vec::with_capacity(count);
    for idx in 0..count {
        let r = next_entropy_u64();
        if idx % 2 == 0 {
            words.push(ADJECTIVES[(r as usize) % ADJECTIVES.len()]);
        } else {
            words.push(NOUNS[(r as usize) % NOUNS.len()]);
        }
    }
    GeneratedPassphrase {
        phrase: words.join(sep),
        word_count: count,
        entropy_bits: (count as u32) * 10,
    }
}

pub fn generate_uuid_v4_local_part() -> String {
    let a = next_entropy_u64();
    let b = next_entropy_u64();
    let b0 = (a >> 32) as u32;
    let b1 = ((a >> 16) & 0xFFFF) as u16;
    let b2 = ((a & 0x0FFF) | 0x4000) as u16;
    let b3 = (((b >> 48) & 0x3FFF) | 0x8000) as u16;
    let b4 = b & 0xFFFF_FFFF_FFFF;
    format!("{:08x}-{:04x}-{:04x}-{:04x}-{:012x}", b0, b1, b2, b3, b4)
}

pub fn generate_alias_preview_candidate(format: &str, domain: &str) -> GeneratedAliasCandidate {
    let clean_dom = if domain.trim().is_empty() {
        "mailx.net".to_string()
    } else {
        domain.trim().trim_start_matches('@').to_ascii_lowercase()
    };
    let clean_fmt = format.trim().to_ascii_lowercase();
    let (local_part, entropy_bits) = match clean_fmt.as_str() {
        "random" => (generate_random_suffix(10), 51),
        "uuid" => (generate_uuid_v4_local_part(), 122),
        "wildcard" => (format!("*+{}", generate_random_suffix(8)), 41),
        _ => (generate_words_local_part(), 27),
    };
    let full_address = format!("{}@{}", local_part, clean_dom);
    GeneratedAliasCandidate {
        full_address,
        local_part,
        domain: clean_dom,
        format: clean_fmt,
        entropy_bits,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_word_and_uuid_generation() {
        assert!(ADJECTIVES.len() > 800);
        assert!(NOUNS.len() > 900);
        let w = generate_words_local_part();
        assert!(w.contains('.'));
        let u = generate_uuid_v4_local_part();
        assert_eq!(u.len(), 36);
        let cand = generate_alias_preview_candidate("words", "mailx.net");
        assert!(cand.full_address.ends_with("@mailx.net"));
        let pp = generate_passphrase(5, "-");
        assert_eq!(pp.word_count, 5);
    }
}
